CREATE OR REPLACE FUNCTION public.riser_visit_customer(_site_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE ancestors AS (SELECT id,parent_id,0 AS depth FROM public.sites WHERE id=_site_id AND org_id=public.get_user_org_id() AND deleted_at IS NULL UNION ALL SELECT s.id,s.parent_id,a.depth+1 FROM public.sites s JOIN ancestors a ON s.id=a.parent_id WHERE s.org_id=public.get_user_org_id() AND s.deleted_at IS NULL AND a.depth<20) SELECT cs.customer_id FROM ancestors a JOIN public.customer_sites cs ON cs.site_id=a.id JOIN public.customers c ON c.id=cs.customer_id WHERE c.org_id=public.get_user_org_id() ORDER BY a.depth,c.id LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.riser_visit_customer(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.riser_visit_customer(uuid) TO authenticated;
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.create_riser_visit(uuid,uuid,date,jsonb,text,text,uuid)'::regprocedure) INTO definition;
 definition:=replace(definition,'SELECT cu.* INTO c FROM public.customers cu JOIN public.customer_sites cs ON cs.customer_id=cu.id WHERE cs.site_id=s.id AND cu.org_id=o ORDER BY cu.id LIMIT 1;','SELECT cu.* INTO c FROM public.customers cu WHERE cu.id=public.riser_visit_customer(s.id) AND cu.org_id=o;');
 definition:=replace(definition,'INSERT INTO public.job_sheet_responses(job_id,template_id,submitted_by,status,responses,system_label,org_id,created_at) VALUES(j.id,t.id,auth.uid(),''draft'',answers,loc,o,now()+position*interval ''1 millisecond'');','answers:=answers||jsonb_build_object(''_visit_prefill'',answers - ''_riser_visit'' - ''_system_label''); INSERT INTO public.job_sheet_responses(job_id,template_id,submitted_by,status,responses,system_label,org_id,created_at) VALUES(j.id,t.id,auth.uid(),''draft'',answers,loc,o,now()+position*interval ''1 millisecond'');');
 EXECUTE definition;
END $$;